(6270700, 926855, 108069, '<td valign="top">Super sharp. Pun was honestly not intended but I kept typing and then caught it and didn''t erase it so there is a point when there is some internal discussion on whether the pun is now intended or if I should rather be talking about how rich the colors are and how well composed this is and how the focal depth is spot on and how it''s a really interesting image. Great one.</td>', 'Super sharp. Pun was honestly not intended but I kept typing and then caught it and didn''t erase it so there is a point when there is some internal discussion on whether the pun is now intended or if I should rather be talking about how rich the colors are and how well composed this is and how the focal depth is spot on and how it''s a really interesting image. Great one.', '2011-01-04 17:23:11.000000', NULL, 1),
(6270701, 926730, 108069, '<td valign="top">Awesome capture.</td>', 'Awesome capture.', '2011-01-04 17:23:26.000000', NULL, 1),
(6270702, 926730, 109227, '<td valign="top">Great image.  My favorite of the challenge.</td>', 'Great image.  My favorite of the challenge.', '2011-01-04 17:25:19.000000', NULL, 1),
(6270703, 926915, 109227, '<td valign="top">Such a beautiful image.  Great job of processing.</td>', 'Such a beautiful image.  Great job of processing.', '2011-01-04 17:26:05.000000', NULL, 1),
(6270704, 926945, 108069, '<td valign="top">That must be mist/fog from a river and/or falls, as the trees below are covered in ice and the trees further up are not. Very interesting photo. Very nice as well.</td>', 'That must be mist/fog from a river and/or falls, as the trees below are covered in ice and the trees further up are not. Very interesting photo. Very nice as well.', '2011-01-04 17:26:29.000000', NULL, 1),
(6270708, 926970, 108069, '<td valign="top">Looks like you were about to as well. Awesome capture.</td>', 'Looks like you were about to as well. Awesome capture.', '2011-01-04 17:27:56.000000', NULL, 1),
(6270709, 926904, 109227, '<td valign="top">Love this image.  Has a Currier &amp; Ives feel to it (except for the cars).  Great DOF.</td>', 'Love this image.  Has a Currier & Ives feel to it (except for the cars).  Great DOF.', '2011-01-04 17:27:58.000000', NULL, 1),
(6270710, 926867, 109227, '<td valign="top">Great snowman.  Makes me smile.</td>', 'Great snowman.  Makes me smile.', '2011-01-04 17:28:14.000000', NULL, 1),
(6270712, 927011, 109227, '<td valign="top">I can really feel the cold here.  Good interpretation.</td>', 'I can really feel the cold here.  Good interpretation.', '2011-01-04 17:29:10.000000', NULL, 1),
(6270713, 926986, 108069, '<td valign="top">Extra point for the Charlie Brown memory. Nice photo. Could be a tad sharper on the red ball''s gold part, but it''s well composed, the focal depth is great and the the bokeh adds as well. nice one.</td>', 'Extra point for the Charlie Brown memory. Nice photo. Could be a tad sharper on the red ball''s gold part, but it''s well composed, the focal depth is great and the the bokeh adds as well. nice one.', '2011-01-04 17:29:42.000000', NULL, 1),
