(6270720, 926929, 108069, '<td valign="top">Wow. Some effort went into this. Well spotted, dramatic scene, and superbly executed. Awesome photo.</td>', 'Wow. Some effort went into this. Well spotted, dramatic scene, and superbly executed. Awesome photo.', '2011-01-04 17:31:56.000000', NULL, 1),
(6270721, 926927, 108069, '<td valign="top">Lovely tones and excellent depth to this. Nice contrast. Clean and sharp. Great.</td>', 'Lovely tones and excellent depth to this. Nice contrast. Clean and sharp. Great.', '2011-01-04 17:32:32.000000', NULL, 1),
