(6271608, 926915, 61084, '<td valign="top">Congrats on your Red. A very pretty scene and nice exposure.</td>', 'Congrats on your Red. A very pretty scene and nice exposure.', '2011-01-05 03:44:31.000000', NULL, 0),
(6271613, 926730, 33361, '<td valign="top">Awwwwwwwwwwww a BIG congrats to you my dear sweet Lydia!!!! LOVE this pic!!</td>', 'Awwwwwwwwwwww a BIG congrats to you my dear sweet Lydia!!!! LOVE this pic!!', '2011-01-05 03:51:33.000000', NULL, 0),
(6271618, 926730, 86799, '<td valign="top">Congratulations, Lydia.  Marvelous shot, blue well deserved.  And thank Jack for us!</td>', 'Congratulations, Lydia.  Marvelous shot, blue well deserved.  And thank Jack for us!', '2011-01-05 04:03:02.000000', NULL, 0),
(6271651, 926730, 41337, '<td valign="top">Now that''s just silly!</td>', 'Now that''s just silly!', '2011-01-05 04:37:39.000000', NULL, 0),
(6271657, 926730, 92847, '<td valign="top">Congratulations, Lydia, fantastic photo!</td>', 'Congratulations, Lydia, fantastic photo!', '2011-01-05 04:43:10.000000', NULL, 0),
(6271660, 926915, 92847, '<td valign="top">Awesome image! Congratulations!</td>', 'Awesome image! Congratulations!', '2011-01-05 04:45:21.000000', NULL, 0),
(6271682, 926842, 67258, '<td valign="top">Way under appreciated - it was in my top 5 of the challenge.  The smallness of the image didn''t bother me at all; I was less sue about the heavy black border - at the top it is almost crushing down on the children at play, which is at odds with the title and subject.  That said, it throws up an interesting feeling of dissonance - almost reinforcing the idea of the fleeting nature of childhood, and perhaps of joy, as the realities of the adult world way down on us.  Ok, getting far too philosophical, let me just say that this is a photo that works for me!</td>', 'Way under appreciated - it was in my top 5 of the challenge.  The smallness of the image didn''t bother me at all; I was less sue about the heavy black border - at the top it is almost crushing down on the children at play, which is at odds with the title and subject.  That said, it throws up an interesting feeling of dissonance - almost reinforcing the idea of the fleeting nature of childhood, and perhaps of joy, as the realities of the adult world way down on us.  Ok, getting far too philosophical, let me just say that this is a photo that works for me!', '2011-01-05 05:37:50.000000', NULL, 0),
(6271683, 926904, 67258, '<td valign="top">Was looking forward to seeing this on the front page for the next week, but ot too be.  Nonetheless, an HM is good.  Love the photo, but the series of three as a whole is absolutely cracking.  You <b>must</b> get these printed large (maybe canvases) and have them hanging on your wall!</td>', 'Was looking forward to seeing this on the front page for the next week, but ot too be.  Nonetheless, an HM is good.  Love the photo, but the series of three as a whole is absolutely cracking.  You must get these printed large (maybe canvases) and have them hanging on your wall!', '2011-01-05 05:48:45.000000', NULL, 0),
(6271686, 926915, 67258, '<td valign="top">You found that Leica magic! Gorgeous photo, and delighted to see it on the front page.</td>', 'You found that Leica magic! Gorgeous photo, and delighted to see it on the front page.', '2011-01-05 05:54:41.000000', NULL, 0),
